const adapter = window.__ai4a11yShowCaptions;
if (!adapter || !adapter.enabled) return true;

const v = document.getElementById('video-multilingual');
if (!v) return false;
const en = [...v.textTracks].find((t) => t.language === 'en' && t.kind === 'captions');
if (!en) return false;

// 1. User turns captions off
en.mode = 'disabled';
// Re-running sweep or enable() must NOT re-enable captions on handled video
adapter.enable();
if (en.mode !== 'disabled') return false;
// Restore showing for remaining tests
en.mode = 'showing';

// 2. Dynamic media insertion
const newVideo = document.createElement('video');
newVideo.id = 'video-dynamic-test';
const newTrack = document.createElement('track');
newTrack.kind = 'captions';
newTrack.srclang = 'en';
newTrack.label = 'English';
newTrack.src = 'data:text/vtt,WEBVTT%0A%0A00:00:00.000%20--%3E%2000:00:05.000%0ADynamic';
newVideo.appendChild(newTrack);
document.getElementById('seminars').appendChild(newVideo);

// Allow track to register and run sweep
await new Promise((r) => setTimeout(r, 50));
adapter.enable();
const dynTracks = [...newVideo.textTracks];
const dynEn = dynTracks.find((t) => t.language === 'en');
const dynamicHandled = dynEn && dynEn.mode === 'showing';

// Clean up injected video
newVideo.remove();

return Boolean(dynamicHandled);

const btnAction = document.getElementById('btn-download-quantum');
const searchInput = document.getElementById('search-input');
const searchBtn = document.getElementById('btn-search');
const ccBtn = document.querySelector('.ytp-subtitles-button');
const navLink = document.getElementById('nav-lectures');
if (!btnAction || !searchInput || !searchBtn || !ccBtn || !navLink) return false;

for (const el of [btnAction, searchBtn, ccBtn]) {
  el.scrollIntoView();
  const rect = el.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;

  el.focus();
  if (document.activeElement !== el) return false;

  const style = window.getComputedStyle(el);
  const outlineWidth = parseFloat(style.outlineWidth) || 0;
  if (outlineWidth < 2) return false;

  const hit = document.elementFromPoint(rect.left + rect.width / 2, rect.top + rect.height / 2);
  if (hit !== el && !el.contains(hit)) return false;

  el.blur();
}

window.scrollTo(0, 0);
return true;

